mappings.PAY.response:
status = 200
  ? (body.accepted = true and $type(body.ttId) = "string" and body.ttId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.ttId, "code": body.errCode}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 422 and $type(body.errCode) = "string" and body.errCode != ""
  ? {"outcome": "FAILED", "code": body.errCode, "message": body.errText}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.INQUIRY.response:
status = 200
  ? (body.accepted = true and $type(body.billId) = "string" and $type(body.outstandingTaka) = "string" and $type(body.minimumTaka) = "string"
      ? {"outcome": "SUCCESS", "partnerRef": body.billId, "code": body.errCode, "attributes": {"outstanding": body.outstandingTaka, "minimum": body.minimumTaka}}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 422 and $type(body.errCode) = "string" and body.errCode != ""
  ? {"outcome": "FAILED", "code": body.errCode, "message": body.errText}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.STATUS_QUERY.response:
status = 200
  ? (body.accepted = true and $type(body.ttId) = "string" and body.ttId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.ttId, "code": body.errCode}
      : body.accepted = false and $type(body.errCode) = "string" and body.errCode != ""
        ? {"outcome": "FAILED", "code": body.errCode, "message": body.errText}
        : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 404 and body.accepted = false
  ? {"outcome": "NOT_FOUND", "code": body.errCode, "message": body.errText}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.REVERSE.response:
status = 200
  ? (body.accepted = true and $type(body.ttId) = "string" and body.ttId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.ttId, "code": body.errCode}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 404 or status = 422) and $type(body.errCode) = "string" and body.errCode != ""
  ? {"outcome": "FAILED", "code": body.errCode, "message": body.errText}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}
